<script setup lang="ts">
import UiIcon from '../components/UiIcon.vue'
import{computed,ref}from'vue';import{useApi,useEvents,useAction,stamp}from'../composables/api';import{route}from'../composables/state'
const api=useApi(),info=ref<any>({status:{}}),feed=ref(''),auto=ref(false),autoCleanup=ref(true),{busy,message,run}=useAction()
const statusText=computed(()=>message.value||info.value.status?.error||(info.value.status?.pending?'Ожидаем запуск '+info.value.status.pending:info.value.status?.available?'Доступна '+info.value.status.latest:'Установлена '+(info.value.installed||'…'))+(info.value.feed?'':' · источник обновлений не настроен'))
const checkedText=computed(()=>'Последняя проверка: '+stamp(info.value.status?.checked)+'\nПредыдущая сборка: '+(info.value.previous||'нет'))
const spaceText=computed(()=>info.value.free===undefined?'':'Свободно: '+(info.value.free/1048576).toFixed(1)+' МБ · для обновления: '+Math.ceil(info.value.required_free/1048576)+' МБ')
const cleanupText=computed(()=>{const c=info.value.cleanup||{};return c.checked?'Последняя очистка: '+stamp(c.checked)+' · '+(c.skipped||('удалено объектов: '+(c.removed||[]).length+', освобождено: '+((c.freed||0)/1048576).toFixed(1)+' МБ'))+((c.errors||[]).length?' · Есть ошибки: '+c.errors.join('; '):''):'Автоочистка ещё не выполнялась.'})
let baseline=''
async function load(force=false){try{info.value=await api('/api/native/updates');if(force||!baseline||JSON.stringify([feed.value,auto.value,autoCleanup.value])===baseline){feed.value=info.value.feed||'';auto.value=info.value.auto;autoCleanup.value=info.value.auto_cleanup!==false;baseline=JSON.stringify([feed.value,auto.value,autoCleanup.value])}}catch(e){message.value=(e as Error).message}}
function operate(action:string){void run(async()=>{await api('/api/native/updates/'+action,{});message.value='';await load()})}
function save(){void run(async()=>{await api('/api/native/updates/config',{feed:feed.value.trim(),auto:auto.value,auto_cleanup:autoCleanup.value});message.value='';await load(true)})}
function install(action:string){if(!confirm((action==='apply'?'Установить обновление':'Вернуться к предыдущей версии')+'? Панель перезапустится. Настройки сохранятся.'))return;void run(async()=>{await api('/api/native/updates/'+action,{});message.value='Перезапуск…';setTimeout(()=>location.reload(),20000)})}
void load();useEvents(()=>{if(['updates','settings'].includes(route.active))void load()})
</script>
<template><header class="page-head"><h1><UiIcon name="refresh"/>Обновления панели</h1></header><section class="card" id="native-updates"><div class="card-head"><h2><UiIcon name="refresh"/>Обновления панели</h2><span class="badge ok">На колонке</span></div>
<p class="hint">ПК не нужен. Обновляется только панель; runtime, данные, YAM и прошивка не заменяются.</p>
<label class="set-item"><div class="set-label"><b>Источник обновлений</b><small>HTTPS-манифест из своего репозитория GitHub</small></div><div class="set-ctl"><input class="field" id="native-feed" type="url" placeholder="https://raw.githubusercontent.com/…/update.json" aria-label="Источник обновлений" v-model="feed"></div></label>
<label class="toggle"><span>Автоматически проверять и устанавливать обновления</span><input type="checkbox" id="native-auto" v-model="auto"></label>
<div class="row"><button class="btn" id="native-save" @click="save" :disabled="busy"><UiIcon name="check"/>Сохранить</button><button class="btn" id="native-check" @click="operate('check')" :disabled="busy||!feed"><UiIcon name="refresh"/>Проверить</button><button class="btn primary" id="native-apply" @click="install('apply')" :disabled="busy" :hidden="!info.status?.available"><UiIcon name="dl"/>Установить обновление</button></div><p class="hint" id="native-update-status">{{ statusText }}</p><pre class="out" id="native-notes">{{ info.status?.notes||'Описание изменений отсутствует.' }}</pre><p class="hint" id="native-checked">{{ checkedText }}</p><label class="toggle"><span>Автоматически очищать неиспользуемые сборки панели</span><input type="checkbox" id="native-cleanup-auto" checked v-model="autoCleanup"></label><p class="hint">Очистка каждый час и перед проверкой/установкой обновления. Сохраняются текущая и предыдущая сборки, данные приложений и резервные копии.</p><p class="hint" id="native-space">{{ spaceText }}</p><p class="hint" id="native-cleanup-status">{{ cleanupText }}</p><button class="btn" id="native-cleanup" @click="operate('cleanup')" :disabled="busy"><UiIcon name="trash"/>Очистить сейчас</button><button class="btn danger" id="native-rollback" @click="install('rollback')" :disabled="busy||!info.previous||!!info.status?.pending"><UiIcon name="undo"/>Вернуться к предыдущей версии</button></section><section class="card"><h2><UiIcon name="info"/>Источник обновлений</h2><p class="hint">Укажи HTTPS-адрес update.json своего репозитория GitHub. Пока релиз не опубликован, проверка через интернет недоступна. Автообновление скачивает и устанавливает новую сборку каждые 6 часов; при неудачном запуске служба возвращает предыдущую.</p></section></template>